  'Dark academia': ['key', 'feather', 'crown', 'diamond', 'band', 'triple', 'swirls', 'branches', 'raven', 'fancy'],
  'Fantasy map': ['dragon', 'compass', 'sword', 'crown', 'wings', 'key', 'star', 'bow', 'raven'],
  'Romance': ['rose', 'flower', 'heart', 'feather', 'swirls', 'fancy', 'birds', 'knot'],
  'Thriller': ['band', 'triple', 'diamond', 'key', 'sword'],
  'Sci-fi': ['star', 'moon', 'sun', 'circles'],
  'Fairy tale': ['crown', 'star', 'flower', 'wings', 'heart', 'swirls', 'fancy', 'bow', 'knot'],
  'Seaside': ['compass', 'sun', 'star', 'circles', 'birds'],
