  'Western': ['star', 'sun', 'compass', 'band'],
  avatar: ['sun', 'moon', 'leaf', 'snowflake'], twd: ['band', 'triple', 'lines', 'branches'], hp: ['star', 'key', 'crown', 'wings'],
  lotr: ['crown', 'sword', 'leaf', 'star'], got: ['crown', 'sword', 'dragon', 'snowflake', 'raven'], firefly: ['star', 'moon', 'band'],
