let seedingBooks = false;
// settings.bookStarters remembers which starters were given (by title), so one you
// delete doesn't come back, and starters added later still arrive once.
async function seedBookStarters() {
  const given = Array.isArray(state.settings.bookStarters) ? state.settings.bookStarters
    : state.settings.bookStarters ? BOOK_STARTERS.slice(0, 3).map(libKey) : [];
  if (seedingBooks || !isOwner() || BOOK_STARTERS.every(st => given.includes(libKey(st)))) return;
  seedingBooks = true;
  try {
    const have = new Set(state.books.map(b => libKey(b)));
    let order = Math.max(-1, ...state.books.filter(b => shelfOf(b) === 'want').map(b => b.order ?? 0)) + 1;
    for (const st of BOOK_STARTERS) {
      if (given.includes(libKey(st)) || have.has(libKey(st))) continue;
      const w = st.worldTheme && state.worlds.find(x => x.theme === st.worldTheme);
      await DB.addBook({
        ...st, worldId: w ? w.id : null, shelf: hasShelf('want') ? 'want' : shelvesOf()[0].id, order: order++,
        reads: [{ start: '', end: '', physical: true, audio: false }], rating: 0, page: 0, chapter: '',
        review: '', reviewSafe: '', ending: '', mapOn: false, canonOn: false, reviewsOn: true, ficsOn: false,
      });
    }
    const all = BOOK_STARTERS.map(libKey);
    await DB.saveSettings({ bookStarters: all });
    state.settings.bookStarters = all;
  } catch (e) { console.error(e); }
  seedingBooks = false;
}

const libKey = b => `${(b.title || '').trim().toLowerCase()}|${(b.author || '').trim().toLowerCase()}`;
const photoLink = p => (p && p.url ? { url: p.url, thumbUrl: p.thumbUrl || p.url, w: p.w || null, h: p.h || null } : null);

// Your books, as library entries (only what's safe to share).
let lastBookLibrary = null;
function publishBookLibrary() {
  if (!isOwner() || !DB.saveBookLibrary) return;
  const books = state.books.map(b => ({
    id: b.id, title: b.title || '', author: b.author || '', series: b.series || '', seriesNo: b.seriesNo || '', pages: b.pages || null,
    totalChapters: b.totalChapters || null,
    coverUrl: b.coverUrl || '', coverThumb: b.coverThumb || '', cover: photoLink(b.cover), blurb: b.blurb || '',
    theme: b.theme || 'custom', look: b.look ? { ...b.look, photo: photoLink(b.look.photo) } : null,
    spineFont: b.spineFont || '', spineInk: b.spineInk || '', spineBg: b.spineBg || '', ribbonColor: b.ribbonColor || '', spineOrn: ornOf(b), spineBottom: b.spineBottom || '', spineTop: b.spineTop || '',
    map: photoLink(b.map), mapOn: !!b.mapOn || !!b.map, canonOn: !!b.canonOn,
    // The world it goes with, by its built-in look (so it links to their own copy of that world).
    worldTheme: ((w => (w && w.theme !== 'custom' ? w.theme : '')))(b.worldId && worldById(b.worldId)),
    canonParts: b.canonParts || { ending: true, ships: true, headcanons: true }, reviewsOn: b.reviewsOn !== false, ficsOn: b.ficsOn === true,
  })).sort((a, b) => titleKey(a.title).localeCompare(titleKey(b.title)));
  const json = JSON.stringify(books);
  if (json === lastBookLibrary) return;
  lastBookLibrary = json;
  DB.saveBookLibrary({ books }).catch(e => console.warn('Could not publish the book library', e));
}

// Library books this person doesn't have yet.
function libChoices(lib) {
  const mine = new Set(state.books.map(b => b.fromLib).filter(Boolean));
  const keys = new Set(state.books.map(libKey));
  return ((lib && lib.books) || []).filter(e => !mine.has(e.id) && !keys.has(libKey(e)));
}
const bookLibrary = () => state.bookLibraryP || Promise.resolve(null);

function libCoverHtml(e) {
  const src = (e.cover && (e.cover.thumbUrl || e.cover.url)) || e.coverThumb || e.coverUrl;
  return src ? `<img class="cover-img" src="${esc(src)}" alt="Cover of ${esc(e.title)}" loading="lazy">`
    : `<span class="gen-cover" data-lib-cover="${esc(e.id)}"><span class="gc-title">${esc(e.title)}</span>${e.author ? `<span class="gc-author">${esc(e.author)}</span>` : ''}</span>`;
}
function paintLibCovers(root, entries) {
  $$('[data-lib-cover]', root).forEach(el => { const e = entries.find(x => x.id === el.dataset.libCover); if (e) Themes.apply(el, { theme: e.theme, look: e.look }); });
}

// Puts a library book on this person's shelf (their own copy of every picture).
// worldIds: { theme: id } for worlds added a moment ago (sign-up), to link the book to.
async function addFromLibrary(e, shelf, worldIds = {}) {
  const onShelf = state.books.filter(x => shelfOf(x) === shelf);
  const data = {
    title: e.title, author: e.author, series: e.series, seriesNo: e.seriesNo, pages: e.pages || null, totalChapters: e.totalChapters || null,
    coverUrl: e.coverUrl || '', coverThumb: e.coverThumb || '', blurb: e.blurb || '',
    theme: e.theme || 'custom', look: e.look ? { ...e.look, photo: null } : null,
    spineFont: e.spineFont || '', spineInk: e.spineInk || '', spineBg: e.spineBg || '', ribbonColor: e.ribbonColor || '', spineOrn: e.spineOrn || '', spineBottom: e.spineBottom || '', spineTop: e.spineTop || '',
    // Canon and Fics always start off (there's nothing in them yet); they can turn them on in the book's settings.
    mapOn: !!e.mapOn, canonOn: false, canonParts: e.canonParts || { ending: true, ships: true, headcanons: true },
    reviewsOn: e.reviewsOn !== false, ficsOn: false, fromLib: e.id,
    worldId: (e.worldTheme && (worldIds[e.worldTheme] || (state.worlds.find(w => w.theme === e.worldTheme) || {}).id)) || null,
    shelf, order: Math.max(-1, ...onShelf.map(x => x.order ?? 0)) + 1, rating: 0, page: 0, chapter: '', review: '', reviewSafe: '', ending: '',
    reads: [{ start: shelf === 'reading' ? today() : '', end: shelf === 'read' ? today() : '', physical: true, audio: false }],
  };
  checkPhotoRoom((e.cover ? 1 : 0) + (e.map ? 1 : 0) + (e.look && e.look.photo ? 1 : 0));
  const id = await DB.addBook(data);
  const patch = {};
  const copy = async p => { try { return await DB.copyPhoto('books', id, p); } catch (x) { console.warn('Picture not copied', x); return null; } };
  if (e.cover) { const c = await copy(e.cover); if (c) patch.cover = c; }
  if (e.map) { const m = await copy(e.map); if (m) patch.map = m; }
  if (e.look && e.look.photo) { const ph = await copy(e.look.photo); if (ph) patch.look = { ...data.look, photo: ph }; }
  if (Object.keys(patch).length) await DB.updateBook({ id }, patch);
  return id;
}

// After picking worlds the first time: on to books, if the library has any.
async function afterWorldsPick() {
  const lib = await bookLibrary();
  return libChoices(lib).length && !state.settings.booksPicked ? '#/books/pick' : null;
}

// "Pick your books": the first-time step, and the empty bookcase's way in.
function renderBookPick() {
  view.innerHTML = '<p class="loading">Opening the library…</p>';
  bookLibrary().then(lib => { if (parseHash()[0] === 'books' && parseHash()[1] === 'pick') drawBookPick(lib); });
}

function drawBookPick(lib) {
  // Step 2 of signing up (library.js): picks are kept for the last step, not saved yet.
  const wizard = isOnboarding();
  if (wizard) onboardPicks().hadBooks = true;
  const firstTime = !state.settings.booksPicked;
  const choices = libChoices(lib);
  const def = hasShelf('want') ? 'want' : shelvesOf()[0].id;
  const picked = wizard ? onboardPicks().books : new Map();
  const shelfSelect = sel => `${shelvesOf().map(s => `<option value="${esc(s.id)}" ${s.id === sel ? 'selected' : ''}>${esc(s.name)}</option>`).join('')}`;
  view.innerHTML = `<div class="library books-pick">
    ${wizard ? `${stepDots(2)}<header class="w-head"><a class="back" href="#/library">‹ Back to worlds</a></header>` : '<header class="w-head"><a class="back" href="#/books">‹ Books</a></header>'}
    <header class="lib-head"><div class="lib-crest" aria-hidden="true">${BOOK_CREST}</div>
      <h1 class="lib-title">Pick your books</h1>
      <p class="lib-sub">${firstTime ? 'Tap the ones you want on your shelves. You can add more anytime, and your own too.' : 'Tap the ones you want on your shelves.'}</p></header>
    ${choices.length ? `<div class="pick-books">${choices.map(e => `<div class="pick-book${picked.has(e.id) ? ' picked' : ''}" data-lib="${esc(e.id)}">
        <button type="button" class="pick-cover" aria-pressed="${picked.has(e.id)}" aria-label="${esc(e.title)}">${libCoverHtml(e)}<span class="pick-check" aria-hidden="true">✓</span></button>
        <span class="pick-title">${esc(e.title)}</span>${e.author ? `<span class="pick-author">${esc(e.author)}</span>` : ''}
        <label class="mini-field pick-shelf" ${picked.has(e.id) ? '' : 'hidden'}><span>Shelf</span><select>${shelfSelect(picked.get(e.id) || def)}</select></label></div>`).join('')}</div>`
      : '<p class="empty">You already have every book in the library.</p>'}
    <div class="pick-bar">${wizard ? '<button class="btn primary block" id="next">Next ›</button>'
      : `${choices.length ? '<button class="btn primary block" id="go" disabled>Pick a book</button>' : ''}
      <button class="linkish skip-link" id="skip">${firstTime ? 'Skip for now' : 'Back to my books'}</button>`}</div>
  </div>`;
  paintLibCovers(view, choices);
  if (wizard) $('#next').onclick = () => { location.hash = '#/start'; };
  const go = $('#go');
  const label = () => { if (!go) return; go.disabled = !picked.size; go.textContent = picked.size ? `Put ${picked.size === 1 ? 'it' : `these ${picked.size}`} on my shelves` : 'Pick a book'; };
  $$('.pick-book').forEach(el => {
    const e = choices.find(x => x.id === el.dataset.lib);
    const btn = $('.pick-cover', el), sel = $('select', el);
    btn.onclick = () => {
      if (picked.has(e.id)) picked.delete(e.id); else picked.set(e.id, sel.value);
      const on = picked.has(e.id);
      el.classList.toggle('picked', on);
      btn.setAttribute('aria-pressed', on);
      $('.pick-shelf', el).hidden = !on;
      label();
    };
    sel.onchange = () => { if (picked.has(e.id)) picked.set(e.id, sel.value); };
  });
  const finish = async () => {
    if (!state.settings.booksPicked) { await DB.saveSettings({ booksPicked: true }); state.settings.booksPicked = true; }
  };
  if (wizard) return;
  $('#skip').onclick = () => busy($('#skip'), async () => { await finish(); location.hash = !picked.size && state.worlds.length && firstTime ? '#/' : '#/books'; }, '…');
  if (go) {
    go.onclick = () => busy(go, async () => {
      let n = 0;
      for (const [id, shelf] of picked) {
        go.textContent = `Shelving ${++n} of ${picked.size}…`;
        await addFromLibrary(choices.find(x => x.id === id), shelf);
      }
      await finish();
      toast(picked.size === 1 ? 'It’s on your shelf' : `${picked.size} books on your shelves`);
      location.hash = '#/books';
    }, 'Shelving…');
  }
}

// "From the library" on Add a book: tap one to put it on a shelf.
function fillFromLibrary(defShelf) {
  bookLibrary().then(lib => {
    const box = $('#fromlib');
    if (!box) return;
    const choices = libChoices(lib);
    if (!choices.length) return;
    box.hidden = false;
    if ($('#findh')) $('#findh').textContent = 'Or find another';
    $('.lib-row', box).innerHTML = choices.map(e => `<button type="button" class="lib-book" data-lib="${esc(e.id)}" aria-label="${esc(e.title)}">${libCoverHtml(e)}<span class="lib-book-title">${esc(e.title)}</span></button>`).join('');
    paintLibCovers(box, choices);
    $$('.lib-book', box).forEach(el => {
      el.onclick = () => {
        const e = choices.find(x => x.id === el.dataset.lib);
        const shelfNow = ($('#shelf') && $('#shelf').value) || defShelf;
        openModal(`<div class="lib-detail"><div class="lib-detail-cover">${libCoverHtml(e)}</div>
            <div><h2>${esc(e.title)}</h2>${e.author ? `<p class="muted">${esc(e.author)}</p>` : ''}${e.series ? `<p class="muted small">${esc(e.series)}${e.seriesNo ? ` · Book ${esc(e.seriesNo)}` : ''}</p>` : ''}</div></div>
          ${e.blurb ? `<p class="lib-blurb">${esc(e.blurb)}</p>` : ''}
          <label class="field"><span class="field-label">Put it on</span><select id="lshelf">${shelvesOf().map(sh => `<option value="${esc(sh.id)}" ${sh.id === shelfNow ? 'selected' : ''}>${esc(sh.name)}</option>`).join('')}</select></label>
          <div class="actions"><span class="spacer"></span><button class="btn" data-close>Cancel</button><button class="btn primary" id="ladd">Add to my shelf</button></div>`,
        (root, close) => {
          paintLibCovers(root, [e]);
          $('#ladd', root).onclick = ev => busy(ev.target, async () => {
            const id = await addFromLibrary(e, $('#lshelf', root).value);
            close();
            location.hash = `#/b/${id}`;
          }, 'Adding…');
        });
      };
    });
  });
}

// ---------- series: a series page, and adding the next book ----------
const seriesHref = name => `#/books/series/${encodeURIComponent(name)}`;
const seriesNum = b => parseFloat(b.seriesNo) || 0;
const finishedBook = b => !!lastEnd(b);
let newBookPrefill = null; // { series, seriesNo } for the next Add a book

// The book after this one in its series, if you've finished this one and don't have the next yet.
function nextInSeries(book) {
  const n = seriesNum(book);
  if (!book.series || !n || !finishedBook(book)) return null;
  const next = Math.floor(n) + 1;
  return state.books.some(b => seriesKey(b) === seriesKey(book) && Math.floor(seriesNum(b)) === next) ? null : next;
}
// The next book in the series that's already on your shelves but not read or started yet.
function waitingNext(book) {
  const n = seriesNum(book);
  if (!book.series || !n || !finishedBook(book)) return null;
  const nb = state.books.filter(b => seriesKey(b) === seriesKey(book) && seriesNum(b) > n && !finishedBook(b))
    .sort((a, z) => seriesNum(a) - seriesNum(z))[0];
  return nb && !inReading(nb) ? nb : null;
}
// A library book (from your bookcase) that is this series' book n, if there is one.
const libSeriesBook = (lib, key, n) => libChoices(lib).find(e => seriesKey(e) === key && Math.floor(seriesNum(e)) === n);

function addSeriesBook(series, n) {
  const mate = state.books.find(b => seriesKey(b) === series.trim().toLowerCase() && b.author);
  newBookPrefill = { series, seriesNo: String(n), author: mate ? mate.author : '' };
  newBookShelf = hasShelf('want') ? 'want' : shelvesOf()[0].id;
  location.hash = '#/books/new';
}

function nextCardHtml(book) {
  const w = waitingNext(book);
  if (w) {
    const shelf = (shelvesOf().find(s => s.id === shelfOf(w)) || {}).name || 'your';
    return `<div class="card next-book" id="nextbook"><div class="nb-text"><span class="nb-head">Next in ${esc(book.series)}</span>
        <span class="nb-title">${esc(w.title)}</span><span class="muted small">On your ${esc(shelf)} shelf</span></div>
        <button class="btn small primary" id="startnext" data-book="${esc(w.id)}">${hasShelf('reading') ? 'Start reading' : 'Open it'}</button></div>`;
  }
  const n = nextInSeries(book);
  if (!n) return '';
  return `<div class="card next-book" id="nextbook"><div class="nb-text"><span class="nb-head">Next in ${esc(book.series)}</span>
      <span class="nb-title" id="nbtitle">Book ${n}</span></div>
      <button class="btn small primary" id="addnext">+ Add book ${n}</button></div>`;
}
function wireNextCard(book, body) {
  // Already on a shelf: one tap moves it to Currently reading, with today as its start date.
  const start = $('#startnext', body);
  if (start) {
    const w = bookById(start.dataset.book);
    start.onclick = () => {
      if (!hasShelf('reading')) { location.hash = `#/b/${w.id}`; return; }
      busy(start, async () => {
        await DB.updateBook(w, shelfMovePatch(w, 'reading'));
        toast(`${w.title} is on Currently reading. Enjoy!`);
        location.hash = `#/b/${w.id}`;
      }, 'Starting…');
    };
    return;
  }
  const btn = $('#addnext', body);
  if (!btn) return;
  const n = nextInSeries(book);
  btn.onclick = () => addSeriesBook(book.series, n);
  // In the library already? Then it's one tap, with its cover and details.
  bookLibrary().then(lib => {
    const e = libSeriesBook(lib, seriesKey(book), n);
    if (!e || !btn.isConnected) return;
    $('#nbtitle', body).textContent = e.title;
    btn.textContent = '+ Add to Want to read';
    btn.onclick = () => busy(btn, async () => {
      const id = await addFromLibrary(e, hasShelf('want') ? 'want' : shelvesOf()[0].id);
      toast(`${e.title} is on your shelf`);
      location.hash = `#/b/${id}`;
    }, 'Adding…');
  });
}

// #/books/series/NAME: every book in the series in order, what's read, and what's missing.
function renderSeries(name) {
  const key = (name || '').trim().toLowerCase();
  const list = sortBooks(state.books.filter(b => seriesKey(b) === key), 'drag');
  if (!list.length) { location.replace('#/books'); return; }
  const display = list[0].series;
  const nums = list.map(seriesNum).filter(n => n > 0);
  const max = Math.max(0, ...nums.map(Math.floor));
  const missing = [];
  for (let i = 1; i <= max; i++) if (!nums.some(n => Math.floor(n) === i)) missing.push(i);
  const done = list.filter(finishedBook).length;
  const rows = [...list.map(b => ({ n: seriesNum(b) || 1e6, b })), ...missing.map(n => ({ n, missing: true }))].sort((a, z) => a.n - z.n);
  const status = b => (finishedBook(b) ? 'Read ✓' : (shelvesOf().find(sh => sh.id === shelfOf(b)) || {}).name || '');
  view.innerHTML = `<div class="page series-page">
    <header class="w-head"><a class="back" href="#/books">‹ Books</a></header>
    <h1 class="w-title small-title">${esc(display)}</h1>
    <div class="ser-progress"><span>${done} of ${list.length + missing.length} read</span>
      <span class="goal-bar"><span style="width:${Math.round((done / (list.length + missing.length)) * 100)}%"></span></span></div>
    <div class="ser-list">${rows.map(r => (r.missing
      ? `<div class="card ser-row missing" data-n="${r.n}"><span class="ser-cover ser-blank">${r.n}</span>
          <span class="ser-txt"><span class="ser-no">Book ${r.n}</span><span class="ser-title muted" data-libtitle="${r.n}">Not on your shelves</span></span>
          <button class="btn small" data-addn="${r.n}">+ Add</button></div>`
      : `<button class="card ser-row" data-book="${esc(r.b.id)}"><span class="ser-cover">${coverHtml(r.b)}</span>
          <span class="ser-txt"><span class="ser-no">${r.b.seriesNo ? `Book ${esc(r.b.seriesNo)}` : 'In the series'}</span><span class="ser-title">${esc(r.b.title)}</span>
          <span class="muted small">${esc(status(r.b))}${r.b.rating ? ` · ${r.b.rating} ★` : ''}</span></span></button>`)).join('')}</div>
    <p class="center"><button class="btn small" id="addafter">+ Add book ${max + 1}</button></p>
  </div>`;
  paintCovers(view);
  $$('.ser-row[data-book]').forEach(el => { el.onclick = () => openBook($('.ser-cover', el), bookById(el.dataset.book)); });
  $('#addafter').onclick = () => addSeriesBook(display, max + 1);
  $$('[data-addn]').forEach(b => { b.onclick = () => addSeriesBook(display, Number(b.dataset.addn)); });
  // Missing books that are in the library: show their titles and add them in one tap.
  bookLibrary().then(lib => {
    $$('.ser-row.missing').forEach(row => {
      const n = Number(row.dataset.n), e = libSeriesBook(lib, key, n);
      if (!e || !row.isConnected) return;
      $('[data-libtitle]', row).textContent = `${e.title} · in the library`;
      const b = $('[data-addn]', row);
      b.onclick = () => busy(b, async () => { await addFromLibrary(e, hasShelf('want') ? 'want' : shelvesOf()[0].id); toast(`${e.title} is on your shelf`); }, 'Adding…');
    });
  });
}

// Hold a card (about half a second), drag it, let go: the same feel as the doors and
// books. onDrop gets the new order (each card's data-* key, from the selector's attribute).
let holdDrag = null;
function enableHoldDrag(box, sel, onDrop) {
  if (!box) return;
  if (holdDrag) holdDrag.abort();
  holdDrag = new AbortController();
  const opts = { signal: holdDrag.signal };
  const attr = /\[data-([a-z-]+)\]/.exec(sel)[1];
  const keyOf = el => el.getAttribute(`data-${attr}`);
  let timer = null, start = null, item = null, ghost = null, offset = null, dragging = false;
  const cancel = () => { clearTimeout(timer); timer = null; };
  const begin = (el, x, y) => { item = el; start = { x, y }; cancel(); timer = setTimeout(pick, 450); };
  function pick() {
    timer = null;
    if (!item || !item.isConnected) return;
    dragging = true;
    const r = item.getBoundingClientRect();
    offset = { x: start.x - r.left, y: start.y - r.top };
    ghost = item.cloneNode(true);
    ghost.classList.add('hold-ghost');
    Object.assign(ghost.style, { left: `${r.left}px`, top: `${r.top}px`, width: `${r.width}px`, height: `${r.height}px` });
    document.body.appendChild(ghost);
    item.classList.add('hold-placeholder');
    if (navigator.vibrate) navigator.vibrate(8);
  }
  function move(x, y) {
    ghost.style.left = `${x - offset.x}px`;
    ghost.style.top = `${y - offset.y}px`;
    const over = document.elementFromPoint(x, y);
    const target = over && over.closest(sel);
    if (!target || target === item || !box.contains(target)) return;
    const list = $$(sel, box);
    box.insertBefore(item, list.indexOf(target) > list.indexOf(item) ? target.nextSibling : target);
  }
  function drop() {
    if (ghost) ghost.remove();
    ghost = null;
    item.classList.remove('hold-placeholder');
    dragging = false;
    box.dataset.draggedAt = Date.now(); // so letting go isn't also taken as a tap
    onDrop($$(sel, box).map(keyOf));
  }
  const end = () => { cancel(); if (dragging) drop(); };
  box.addEventListener('touchstart', e => { const el = e.target.closest(sel); if (el && e.touches.length === 1) begin(el, e.touches[0].clientX, e.touches[0].clientY); }, { passive: true, ...opts });
  box.addEventListener('touchmove', e => {
    const p = e.touches[0];
    if (dragging) { e.preventDefault(); move(p.clientX, p.clientY); return; }
    if (timer && Math.hypot(p.clientX - start.x, p.clientY - start.y) > 10) cancel();
  }, { passive: false, ...opts });
  box.addEventListener('touchend', end, opts);
  box.addEventListener('touchcancel', end, opts);
  box.addEventListener('pointerdown', e => { if (e.pointerType !== 'mouse' || e.button > 0) return; const el = e.target.closest(sel); if (el) begin(el, e.clientX, e.clientY); }, opts);
  window.addEventListener('pointermove', e => {
    if (e.pointerType !== 'mouse') return;
    if (dragging) { move(e.clientX, e.clientY); return; }
    if (timer && Math.hypot(e.clientX - start.x, e.clientY - start.y) > 10) cancel();
  }, opts);
  window.addEventListener('pointerup', e => { if (e.pointerType === 'mouse') end(); }, opts);
  box.addEventListener('contextmenu', e => { if (e.target.closest(sel)) e.preventDefault(); }, opts);
}

// ---------- reading goal & stats ----------
let statsYear = null;
// Whether a stats section is open (By month starts open, Finished starts closed); remembered on this phone.
function statsFold(key, dflt, set) {
  try {
    const all = JSON.parse(localStorage.getItem('fw-stats') || '{}');
    if (set) { all[key] = dflt; localStorage.setItem('fw-stats', JSON.stringify(all)); return dflt; }
    return key in all ? all[key] : dflt;
  } catch { return dflt; }
}
function renderStats() {
  const now = new Date().getFullYear();
  const year = statsYear || now;
  const years = new Set([now]);
  state.books.forEach(b => readsOf(b).forEach(r => { if (r.end) years.add(Number(r.end.slice(0, 4))); }));
  const minY = Math.min(...years), maxY = Math.max(...years);
  const fin = finishesIn(year);
  const goal = goalFor(year);
  const pages = fin.reduce((n, f) => n + (Number(f.book.pages) || 0), 0);
  const fmt = {
    physical: fin.filter(f => f.read.physical && !f.read.audio).length,
    audio: fin.filter(f => f.read.audio && !f.read.physical).length,
    both: fin.filter(f => f.read.audio && f.read.physical).length,
  };
  // Books finished each month, as little stacks of books lying flat (in their spine colors).
  const byMonth = Array.from({ length: 12 }, () => []);
  fin.forEach(f => { byMonth[Number(f.read.end.slice(5, 7)) - 1].push(f); });
  const thisMonth = new Date().getMonth();
  const MAX_STACK = 6;
  const flatBook = (f, k) => {
    const st = spineStyle(f.book);
    const w = 80 + (hashOf(`${f.book.id}${k}`) % 5) * 4;            // 80–96% wide, a little uneven
    const shift = ((hashOf(f.book.title || '') % 5) - 2) * 1.5;      // and not perfectly lined up
    const h = Math.round(Math.min(22, Math.max(16, 13 + (Number(f.book.pages) || 300) / 120)));
    Themes.loadFont(st.font);
    return `<span class="flat-book" style="--fw:${w}%;--fh:${h}px;--fx:${shift}px;--sb:${cssColor(st.bg)};--si:${cssColor(st.ink)};--sf:'${esc(st.font.replace(/'/g, ''))}'"><span class="flat-title">${esc(f.book.title)}</span></span>`;
  };
  const monthCard = (list, i) => {
    const future = year === now && i > thisMonth;
    const shown = list.slice(0, MAX_STACK).reverse();  // first finished at the bottom
    const full = new Date(2000, i, 1).toLocaleDateString(undefined, { month: 'long' });
    const short = new Date(2000, i, 1).toLocaleDateString(undefined, { month: 'short' });
    return `<button class="month-card${future ? ' future' : ''}${list.length ? '' : ' none'}" data-m="${i}" ${list.length ? '' : 'disabled'}>
      <span class="stack">${list.length > MAX_STACK ? `<span class="stack-more">+${list.length - MAX_STACK}</span>` : ''}${shown.map(flatBook).join('')}</span>
      <span class="month-shelf" aria-hidden="true"></span>
      <span class="month-name" data-short="${esc(short)}">${esc(full)}</span>
      <span class="month-count">${list.length ? `${list.length} book${list.length === 1 ? '' : 's'}` : '—'}</span></button>`;
  };
  const pct = goal ? Math.min(100, Math.round((fin.length / goal) * 100)) : 0;
  const fmtTotal = Math.max(1, fmt.physical + fmt.audio + fmt.both);
  // The four tiles, in the order you've dragged them into (settings.statOrder).
  // Five little stars, filled to the rating (halves too).
  const miniStars = r => `<span class="mini-stars" role="img" aria-label="${r} out of 5 stars">${[1, 2, 3, 4, 5].map(n =>
    `<span class="mini-star" style="--fill:${r >= n ? 100 : r >= n - 0.5 ? 50 : 0}%"></span>`).join('')}</span>`;
  // Favorite of the year: one book. The one you picked (settings.favorites[year]), or else your
  // most recently finished book with your highest rating that year. Tap the tile to change it.
  const finBooks = [...new Map(fin.map(f => [f.book.id, f])).values()];
  const best = Math.max(0, ...finBooks.map(f => f.book.rating || 0));
  const picked = (((state.settings || {}).favorites || {})[year]);
  const favF = finBooks.find(f => f.book.id === picked)
    || (best ? finBooks.filter(f => f.book.rating === best).sort((a, z) => z.read.end.localeCompare(a.read.end))[0] : null);
  const fav = favF && favF.book;
  const favHtml = !fav ? '–'
    : `<span class="fav-covers"><span class="fav-cover">${coverHtml(fav)}</span>${fav.rating ? miniStars(fav.rating) : ''}</span>
       <span class="fav-line">${esc(fav.title)}</span>`;
  // Average days per book: start to finish, for reads with both dates.
  const spans = fin.filter(f => f.read.start && f.read.start <= f.read.end)
    .map(f => Math.round((new Date(f.read.end) - new Date(f.read.start)) / 864e5) + 1);
  const days = spans.length ? Math.round(spans.reduce((a, b) => a + b, 0) / spans.length) : null;
  // Want to read: the next few books on that shelf (in its order), and how many are waiting.
  const wantList = hasShelf('want') ? booksOn('want') : [];
  const wantHtml = !wantList.length ? '0'
    : `<span class="fav-covers">${wantList.slice(0, 3).map(b => `<a class="fav-cover" href="#/b/${esc(b.id)}" aria-label="${esc(b.title)}">${coverHtml(b)}</a>`).join('')}</span>
       <span class="fav-line">${wantList.length} book${wantList.length === 1 ? '' : 's'} waiting</span>`;
  const TILES = {
    fav: ['Favorite of the year', favHtml],
    want: ['Up next', wantHtml],
    pages: ['Pages read', pages.toLocaleString()],
    days: ['Average days per book', days == null ? '–' : `${days}<span class="stat-unit"> day${days === 1 ? '' : 's'}</span>`],
  };
  // (Older saved orders used avg and reading for the two tiles these replaced.)
  const renamed = { avg: 'fav', reading: 'days' };
  const saved = ((state.settings || {}).statOrder || []).map(k => renamed[k] || k).filter(k => TILES[k]);
  const order = [...saved, ...Object.keys(TILES).filter(k => !saved.includes(k))];
  const tile = k => `<div class="card stat${(k === 'fav' && fav) || (k === 'want' && wantList.length) ? ' stat-fav' : ''}" data-stat="${k}"><span class="stat-v">${TILES[k][1]}</span><span class="stat-l">${TILES[k][0]}</span></div>`;
  view.innerHTML = `<div class="page stats-page">
    <header class="w-head"><a class="back" href="#/books">‹ Books</a></header>
    <h1 class="w-title small-title">Reading stats</h1>
    <div class="year-nav"><button class="rw-arrow" id="py" aria-label="Previous year" ${year <= minY ? 'disabled' : ''}>‹</button><span class="year">${year}</span><button class="rw-arrow" id="ny" aria-label="Next year" ${year >= maxY ? 'disabled' : ''}>›</button></div>
    <div class="card goal-card">
      <span class="goal-big">${fin.length}${goal ? `<span class="goal-of"> of ${goal}</span>` : ''}</span>
      <span class="muted small">book${fin.length === 1 ? '' : 's'} finished in ${year}</span>
      ${goal ? `<div class="rw-bar"><span style="width:${pct}%"></span></div>` : ''}
      ${goal && fin.length >= goal ? '<p class="goal-done">Goal reached!</p>' : ''}
      <button class="btn small" id="setgoal">${goal ? 'Change goal' : `Set a ${year} goal`}</button>
    </div>
    <div class="stat-grid" id="statgrid">${order.map(tile).join('')}</div>
    <h2 class="sec-h">How I read</h2>
    <div class="card fmt-card">
      <div class="fmt-bar" role="img" aria-label="Physical ${fmt.physical}, audiobook ${fmt.audio}, both ${fmt.both}">
        ${[['physical', fmt.physical], ['audio', fmt.audio], ['both', fmt.both]].filter(([, n]) => n).map(([k, n]) => `<span class="fmt-${k}" style="flex:${n / fmtTotal}"></span>`).join('') || '<span class="fmt-none"></span>'}</div>
      <div class="fmt-keys"><span><i class="fmt-physical"></i>Physical ${fmt.physical}</span><span><i class="fmt-audio"></i>Audiobook ${fmt.audio}</span><span><i class="fmt-both"></i>Both ${fmt.both}</span></div>
    </div>
    <details class="rw-block stat-block" data-block="months" ${statsFold('months', true) ? 'open' : ''}><summary class="block-head"><h2 class="sec-h">By month<span class="fold-caret" aria-hidden="true"></span></h2></summary>
    <div class="months">${byMonth.map(monthCard).join('')}</div></details>
    <details class="rw-block stat-block" data-block="finished" ${statsFold('finished', false) ? 'open' : ''}><summary class="block-head"><h2 class="sec-h">Finished in ${year}<span class="fold-caret" aria-hidden="true"></span></h2></summary>
    ${fin.length ? `<div class="fin-list">${fin.slice().reverse().map(f => `<a class="fin card" href="#/b/${esc(f.book.id)}">
        <span class="fin-cover">${coverHtml(f.book)}</span>
        <span class="fin-txt"><span class="fin-title">${esc(f.book.title)}</span>${f.book.author ? `<span class="muted small">${esc(f.book.author)}</span>` : ''}
        <span class="muted small">${esc(fmtDate(f.read.end))}${f.book.rating ? ` · ${f.book.rating} ★` : ''}${f.i > 0 ? ' · re-read' : ''}</span></span></a>`).join('')}</div>`
      : '<p class="empty">Nothing finished yet this year. The next one’s waiting.</p>'}</details>
  </div>`;
  paintCovers(view);
  // Tap the favorite to choose a different one from the books finished this year.
  const favTile = $('[data-stat="fav"]');
  if (favTile && finBooks.length) {
    favTile.classList.add('tappable');
    favTile.onclick = () => Date.now() - Number($('#statgrid').dataset.draggedAt || 0) < 500 ? null : openModal(`<h2>Favorite of ${year}</h2><p class="muted small">Pick the book that wins the year.</p>
      <div class="fin-list fav-pick">${finBooks.slice().sort((a, z) => (z.book.rating || 0) - (a.book.rating || 0) || z.read.end.localeCompare(a.read.end)).map(f => `<button class="fin card${fav && f.book.id === fav.id ? ' on' : ''}" data-fav="${esc(f.book.id)}">
          <span class="fin-cover">${coverHtml(f.book)}</span>
          <span class="fin-txt"><span class="fin-title">${esc(f.book.title)}</span>${f.book.rating ? miniStars(f.book.rating) : '<span class="muted small">Not rated</span>'}</span></button>`).join('')}</div>
      <div class="actions">${fav ? `<a class="btn ghost" href="#/b/${esc(fav.id)}" data-close>Open ${esc(fav.title)}</a>` : ''}<span class="spacer"></span><button class="btn" data-close>Close</button></div>`, (root, close) => {
      paintCovers(root);
      $$('[data-fav]', root).forEach(b => {
        b.onclick = () => busy(b, async () => {
          const favorites = { ...((state.settings || {}).favorites || {}), [year]: b.dataset.fav };
          await DB.saveSettings({ favorites });
          state.settings.favorites = favorites;
          close();
          renderStats();
        }, '…');
      });
    });
  }
  enableHoldDrag($('#statgrid'), '.stat[data-stat]', keys => {
    state.settings.statOrder = keys;
    DB.saveSettings({ statOrder: keys }).catch(e => toast(friendlyError(e), true));
  });
  // The two sections fold open and closed (remembered on this phone).
  $$('.stat-block').forEach(d => d.addEventListener('toggle', () => statsFold(d.dataset.block, d.open, true)));
  // Stacked-book titles shrink to fit their book; a very long one wraps onto two lines.
  const fitFlat = () => $$('.flat-title').forEach(t => {
    let fs = 8;
    t.style.fontSize = ''; t.classList.remove('two');
    // The text's exact width (scrollWidth rounds, which can hide a sliver of overflow).
    const tooWide = () => { const r = document.createRange(); r.selectNodeContents(t); return r.getBoundingClientRect().width > t.getBoundingClientRect().width - 0.5; };
    while (tooWide() && fs > 5.5) { fs -= 0.25; t.style.fontSize = `${fs}px`; }
    if (tooWide() && t.parentElement.offsetHeight >= 15) {
      t.classList.add('two');
      fs = 6.5; t.style.fontSize = `${fs}px`;
      while (t.scrollHeight > t.clientHeight + 0.5 && fs > 5) { fs -= 0.25; t.style.fontSize = `${fs}px`; }
    }
  });
  fitFlat();
  // Book fonts load as they're needed, so fit again whenever one arrives.
  if (document.fonts) {
    document.fonts.ready.then(() => { if ($('.months')) fitFlat(); });
    const again = () => { if ($('.months')) fitFlat(); else document.fonts.removeEventListener('loadingdone', again); };
    document.fonts.addEventListener('loadingdone', again);
  }
  setTimeout(() => { if ($('.months')) fitFlat(); }, 900);
  // Full month names where they fit; "Sep" where they don't.
  $$('.month-name').forEach(el => { if (el.scrollWidth > el.clientWidth + 1) el.textContent = el.dataset.short; });
  // Tap a month: the books finished then.
  $$('.month-card[data-m]').forEach(card => {
    card.onclick = () => {
      const list = byMonth[Number(card.dataset.m)];
      if (!list.length) return;
      const name = new Date(2000, Number(card.dataset.m), 1).toLocaleDateString(undefined, { month: 'long' });
      openModal(`<h2>${esc(name)} ${year}</h2><div class="fin-list month-list">${list.map(f => `<a class="fin card" href="#/b/${esc(f.book.id)}" data-close>
          <span class="fin-cover">${coverHtml(f.book)}</span>
          <span class="fin-txt"><span class="fin-title">${esc(f.book.title)}</span>${f.book.author ? `<span class="muted small">${esc(f.book.author)}</span>` : ''}
          <span class="muted small">Finished ${esc(fmtDate(f.read.end))}${f.book.rating ? ` · ${f.book.rating} ★` : ''}${f.i > 0 ? ' · re-read' : ''}</span></span></a>`).join('')}</div>
        <div class="actions"><span class="spacer"></span><button class="btn" data-close>Close</button></div>`, root => paintCovers(root));
    };
  });
  $('#py').onclick = () => { statsYear = year - 1; renderStats(); };
  $('#ny').onclick = () => { statsYear = year + 1; renderStats(); };
  $('#setgoal').onclick = () => formModal({
    title: `${year} reading goal`,
    values: { goal: goal || '' },
    fields: [{ key: 'goal', label: 'How many books?', type: 'number', placeholder: '30' }],
    onSave: async v => {
      const goals = { ...((state.settings || {}).goals || {}), [year]: Number(v.goal) || 0 };
      await DB.saveSettings({ goals });
      state.settings.goals = goals;
      renderStats();
    },
  });
}
